SET lock_timeout = '5s';

-- Daily Pages is now Short Response (Brian, Nov 15). Daily Pages used to cover
-- any in-class writing; Class Starter and Exit Ticket took that over, and the
-- old name confused teachers. Short Response is the one or two paragraph
-- analysis, explanation or reflection.
--
-- Only the name and the card change. The `daily_pages` kind, the rubric and
-- every assignment and submission under the type are untouched, and the app
-- accepts either title. A title a school has already changed is left alone,
-- and a database without these rows is a no-op.

-- title
UPDATE "AssignmentType"
SET
  "title" = 'Short Response',
  "updatedAt" = CURRENT_TIMESTAMP
WHERE
  "kind" = 'daily_pages'
  AND "title" = 'Daily Pages';

-- module
UPDATE "AssignmentModule" AS m
SET
  "title" = 'Short Response',
  "updatedAt" = CURRENT_TIMESTAMP
FROM "AssignmentType" AS t
WHERE m."assignmentTypeId" = t."id"
  AND t."kind" = 'daily_pages'
  AND m."title" = 'Daily Pages';

-- card
-- The card on this type was the cat above a "Class Starter" wordmark. The new
-- one is the cat holding up a page with two short paragraphs, and no wordmark
-- (the tile already prints the title). Production does not run the card
-- seeds, so this is how it gets there. Only that one drawing is replaced: a
-- card somebody uploaded themselves is left alone.
UPDATE "AssignmentTypeImage" AS img
SET
  "updatedAt" = NOW(),
  "altText" = 'A scratchy ink drawing of a smiling cat holding up a page with two short paragraphs, on torn white paper.',
  "contentType" = 'image/jpeg',
  "blob" = decode(
    '',
    'base64'
  )
FROM "AssignmentType" AS t
WHERE img."assignmentTypeId" = t."id"
  AND t."kind" = 'daily_pages'
  AND md5(img."blob") = 'de6553790d16191d326bbde20b893ced';
